// self-host: OpenAI-compatible endpoints with a durable, isolated session store
var builder = WebApplication.CreateBuilder(args);
var hosted = builder.AddAIAgent("weather-agent", (_, _) => agent);
builder.Services.AddSingleton<AgentSessionStore, MyAgentSessionStore>();
if (builder.Environment.IsDevelopment()) hosted.WithInMemorySessionStore(withIsolation: false);
else hosted.WithSessionStore((sp, _) => sp.GetRequiredService<AgentSessionStore>());

var app = builder.Build();
app.MapOpenAIResponses(hosted);
app.MapOpenAIChatCompletions(hosted);
app.Run();

// Foundry hosted (Responses)
var fb = AgentHost.CreateBuilder(args);
fb.Services.AddFoundryResponses(agent);
fb.RegisterProtocol("responses", e => e.MapFoundryResponses());
fb.Build().Run();
